INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, last_verified_at) VALUES ('Fix and Flip Series : Time Hacks', 'Conscious Real Estate Investing in Baltimore City', 'Real Estate', 'MONDAY 5 PM PST 7 PM CST 8 PM EST [SIGN UP HERE](https://link.elitereimm.com/widget/form/wSbrsstjtpMx77vSSif7?am_id=debbie5574) Use CRM,', 'MONDAY 5 PM PST 7 PM CST 8 PM EST [SIGN UP HERE](https://link.elitereimm.com/widget/form/wSbrsstjtpMx77vSSif7?am_id=debbie5574) Use CRM, systems, automation, and AI to run flips more efficiently without letting every project take over your life. Fixing and flipping can become a full-time job fast. Contractors need answers. Materials need to be ordered. Draws need to be tracked. Budgets change. Inspections get scheduled. Properties need to be marketed. And somehow you are still supposed to find More info: https://www.meetup.com/conscious-real-estate-investing-in-baltimore-city/events/316780669/', '2026-10-12T20:00:00-04:00', 'Online event', 'Online event', 'Baltimore', 'MD', '', 39.28, -76.65, 'Conscious Real Estate Investing in Baltimore City', 1, true, 'Free', 'live', 'meetup', 'https://www.meetup.com/conscious-real-estate-investing-in-baltimore-city/events/316780669/', now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO UPDATE SET attendee_count=EXCLUDED.attendee_count, starts_at=EXCLUDED.starts_at, status='live', last_verified_at=now();
INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, last_verified_at) VALUES ('[Virtual] Simple Real Estate Strategies That Work (Fun, Free, & Gets You Paid!)', 'Conscious Real Estate Investing in Baltimore City', 'Real Estate', '**Most real estate trainings are like bad lectures:** boring, overloaded with information, and leaving you feeling like you’ll need weeks', '**Most real estate trainings are like bad lectures:** boring, overloaded with information, and leaving you feeling like you’ll need weeks of prep just to get started (or worst of all, they just want to sell you their expensive course or coaching). **We decided to do the exact opposite**—and hundreds of agents now agree. Join us **LIVE (virtual) every Wednesday at 9:00 AM CST** for a zero-fluff, action-packed call where active, top-producing agents openly share exactly what’s working right More info: https://www.meetup.com/conscious-real-estate-investing-in-baltimore-city/events/316694280/', '2026-10-14T10:00:00-04:00', 'Online event', 'Online event', 'Baltimore', 'MD', '', 39.28, -76.65, 'Conscious Real Estate Investing in Baltimore City', 1, true, 'Free', 'live', 'meetup', 'https://www.meetup.com/conscious-real-estate-investing-in-baltimore-city/events/316694280/', now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO UPDATE SET attendee_count=EXCLUDED.attendee_count, starts_at=EXCLUDED.starts_at, status='live', last_verified_at=now();
INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, last_verified_at) VALUES ('RE-AI Advantage Lab: Turn AI Into Your Real Estate Advantage', 'Conscious Real Estate Investing in Baltimore City', 'Real Estate', 'AI is changing what “work” looks like for real estate agents. Tasks that used to take hours can now take minutes. Marketing can be created', 'AI is changing what “work” looks like for real estate agents. Tasks that used to take hours can now take minutes. Marketing can be created faster. Follow up can be smarter. Content can be generated almost instantly. But most agents are still trying to figure out **how to actually use AI in their day-to-day business.** That is exactly what we will be exploring inside the **RE-AI Advantage Lab.** This weekly training is designed specifically for real estate agents who want to learn how to use AI More info: https://www.meetup.com/conscious-real-estate-investing-in-baltimore-city/events/316694918/', '2026-10-14T11:00:00-04:00', 'Online event', 'Online event', 'Baltimore', 'MD', '', 39.28, -76.65, 'Conscious Real Estate Investing in Baltimore City', 1, true, 'Free', 'live', 'meetup', 'https://www.meetup.com/conscious-real-estate-investing-in-baltimore-city/events/316694918/', now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO UPDATE SET attendee_count=EXCLUDED.attendee_count, starts_at=EXCLUDED.starts_at, status='live', last_verified_at=now();
INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, last_verified_at) VALUES ('Real Estate Agent Virtual Coffee Mastermind', 'Conscious Real Estate Investing in Baltimore City', 'Real Estate', '**Start your morning...** with a coffee & friends from all over the country. Don''t miss out on our live (virtual) networking event every', '**Start your morning...** with a coffee & friends from all over the country. Don''t miss out on our live (virtual) networking event every Thursday morning. It''s the perfect opportunity to build relationships with Realtors across the state and across the country (sometimes even on the other side of the world) that will serve your clients well when they need a referral. We have a short educational/informative presentation at the beginning of the meeting and then go into 3 or 4 person breakout More info: https://www.meetup.com/conscious-real-estate-investing-in-baltimore-city/events/316709383/', '2026-10-15T10:00:00-04:00', 'Online event', 'Online event', 'Baltimore', 'MD', '', 39.28, -76.65, 'Conscious Real Estate Investing in Baltimore City', 1, true, 'Free', 'live', 'meetup', 'https://www.meetup.com/conscious-real-estate-investing-in-baltimore-city/events/316709383/', now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO UPDATE SET attendee_count=EXCLUDED.attendee_count, starts_at=EXCLUDED.starts_at, status='live', last_verified_at=now();
INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, last_verified_at) VALUES ('Halloween Card Making Workshop🎃 Make 3 Fun Cards!', 'Creative Arts & Crafts with Junko - Los Angeles', 'General Networking', 'Workshop Fee $20 per person - all materials are included. Payment by cash or Venmo at the event. Let’s get creative for Halloween! 🎃👻 In', 'Workshop Fee $20 per person - all materials are included. Payment by cash or Venmo at the event. Let’s get creative for Halloween! 🎃👻 In this fun hands-on workshop, we’ll make 3 different Halloween cards: a Halloween House Card, a Collage Card, and a Pop-Up Card. You’ll take home all 3 handmade cards with envelopes! No experience needed — beginners are very welcome😊 We’ll meet at Hollywood Coffee House. Please support the café by purchasing a drink or snack. ☕️ Come enjoy a relaxing, creative More info: https://www.meetup.com/creative-arts-crafts-with-junko-los-angeles/events/316818380/', '2026-10-17T15:00:00-07:00', 'Hollywood Coffee House', '4972 Hollywood Blvd', 'Los Angeles', 'CA', '', 33.96, -118.27, 'Creative Arts & Crafts with Junko - Los Angeles', 2, false, 'Free', 'live', 'meetup', 'https://www.meetup.com/creative-arts-crafts-with-junko-los-angeles/events/316818380/', now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO UPDATE SET attendee_count=EXCLUDED.attendee_count, starts_at=EXCLUDED.starts_at, status='live', last_verified_at=now();
INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, last_verified_at) VALUES ('Your 15-Minute Breach Plan: Who to Call and What to Do First [ONLINE]', 'Dallas AI for Business Owners & Executives', 'Women in Business', 'In this session we''ll write a one-page breach plan: who to call first, what to shut down, and how to get back to work fast. Most businesses', 'In this session we''ll write a one-page breach plan: who to call first, what to shut down, and how to get back to work fast. Most businesses only discover they have no plan at the worst possible moment. Fifteen minutes of preparation changes that. **What we''ll cover:** • Who to call first, in the right order, and what to tell them • Backups that actually restore, and how to test yours in fifteen minutes • Shared logins and same-day offboarding when someone leaves • The fifteen-minute monthly More info: https://www.meetup.com/dallas-ai-for-business-owners-executives/events/316683893/', '2026-10-12T12:00:00-05:00', 'Online event', 'Online event', 'Dallas', 'TX', '', 32.79, -96.8, 'Dallas AI for Business Owners & Executives', 35, true, 'Free', 'live', 'meetup', 'https://www.meetup.com/dallas-ai-for-business-owners-executives/events/316683893/', now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO UPDATE SET attendee_count=EXCLUDED.attendee_count, starts_at=EXCLUDED.starts_at, status='live', last_verified_at=now();
INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, last_verified_at) VALUES ('How We Got 256 Customers in 90 Days: The AI Sales Funnel, Step by Step [ONLINE]', 'Dallas AI for Business Owners & Executives', 'Women in Business', '**(PLEASE READ THE NOTE AT THE BOTTOM BEFORE YOU RSVP)** A step-by-step walkthrough of the AI sales funnel that brought in 256 paying', '**(PLEASE READ THE NOTE AT THE BOTTOM BEFORE YOU RSVP)** A step-by-step walkthrough of the AI sales funnel that brought in 256 paying customers in 90 days, built for solopreneurs and small business owners. The actual system, the actual numbers, and the AI tools behind each step. Most owners win clients the slow way: referrals, cold outreach and chasing leads who went quiet. That works until things get busy, and then new business stops. An automated funnel solves that. AI now drafts the pages, More info: https://www.meetup.com/dallas-ai-for-business-owners-executives/events/316887217/', '2026-10-14T14:00:00-05:00', 'Online event', 'Online event', 'Dallas', 'TX', '', 32.79, -96.8, 'Dallas AI for Business Owners & Executives', 65, true, 'Free', 'live', 'meetup', 'https://www.meetup.com/dallas-ai-for-business-owners-executives/events/316887217/', now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO UPDATE SET attendee_count=EXCLUDED.attendee_count, starts_at=EXCLUDED.starts_at, status='live', last_verified_at=now();
INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, last_verified_at) VALUES ('Hand It Off: What to Delegate First, with Claude [ONLINE]', 'Dallas AI for Business Owners & Executives', 'Women in Business', 'In this session we''ll sort a typical owner''s week into what only the owner should do and what someone else can own, then use Claude to', 'In this session we''ll sort a typical owner''s week into what only the owner should do and what someone else can own, then use Claude to write the handover so the first task leaves your plate this week. Most owners know they should delegate but never decide what goes first. A clear list and a written handover make it easy to start. **What we''ll cover:** • The three questions that decide what to hand off first • Turning one task into clear written steps with Claude • Handing it to a team member, More info: https://www.meetup.com/dallas-ai-for-business-owners-executives/events/316859907/', '2026-10-16T09:00:00-05:00', 'Online event', 'Online event', 'Dallas', 'TX', '', 32.79, -96.8, 'Dallas AI for Business Owners & Executives', 4, true, 'Free', 'live', 'meetup', 'https://www.meetup.com/dallas-ai-for-business-owners-executives/events/316859907/', now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO UPDATE SET attendee_count=EXCLUDED.attendee_count, starts_at=EXCLUDED.starts_at, status='live', last_verified_at=now();
INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, last_verified_at) VALUES ('Hire the Top 1% Remote Assistant: Find, Test and Train Them with Claude [ONLINE]', 'Dallas AI for Business Owners & Executives', 'Women in Business', 'In this session we''ll walk through how to find, test and hire a top 1% remote assistant who already knows how to use AI, and how Claude', 'In this session we''ll walk through how to find, test and hire a top 1% remote assistant who already knows how to use AI, and how Claude writes the job post, the test task and the training docs for you. Most owners hire their first assistant in a rush, pick the wrong person and end up doing the work twice. A clear role, a short paid test and written training change the outcome. **What we''ll cover:** • Which tasks to hand off first, and the one role that covers them • Where the best AI-savvy More info: https://www.meetup.com/dallas-ai-for-business-owners-executives/events/316836726/', '2026-10-21T14:00:00-05:00', 'Online event', 'Online event', 'Dallas', 'TX', '', 32.79, -96.8, 'Dallas AI for Business Owners & Executives', 6, true, 'Free', 'live', 'meetup', 'https://www.meetup.com/dallas-ai-for-business-owners-executives/events/316836726/', now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO UPDATE SET attendee_count=EXCLUDED.attendee_count, starts_at=EXCLUDED.starts_at, status='live', last_verified_at=now();
